#!/usr/bin/env python3
# -*- coding: ascii -*-
"""
Patch BlokQR : signal "age du domaine" (RDAP), faible poids et fail-open.
Cree app/analyzers/domain_age.py, ajoute 4 reglages a config.py et cable le
pipeline (en parallele de la threat intel, sans rendu). Idempotent : relancable.
A executer depuis /opt/blokqr/backend.
"""
import ast, base64, os, sys

def d(s): return base64.b64decode(s).decode("utf-8")

NEW_FILE = "app/analyzers/domain_age.py"
NEW_FILE_B64 = ""
EDITS = [
    ("app/config.py", "ICAgIHJlZGlyZWN0X2J1ZGdldF9zZWNvbmRzOiBmbG9hdCA9IDEyLjAK", ""),
    ("app/pipeline.py", "ZnJvbSBhcHAuYW5hbHl6ZXJzLmRvbWFpbl9pbnRlbCBpbXBvcnQgYW5hbHl6ZV9kb21haW4K", "ZnJvbSBhcHAuYW5hbHl6ZXJzLmRvbWFpbl9pbnRlbCBpbXBvcnQgYW5hbHl6ZV9kb21haW4KZnJvbSBhcHAuYW5hbHl6ZXJzLmRvbWFpbl9hZ2UgaW1wb3J0IGRvbWFpbl9hZ2Vfc2lnbmFsCg=="),
    ("app/pipeline.py", "ICAgICAgICAgICAgICAgIGR5biwgaW50ZWwgPSBhd2FpdCBhc3luY2lvLmdhdGhlcigKICAgICAgICAgICAgICAgICAgICBfcnVuX2R5bmFtaWMoKSwKICAgICAgICAgICAgICAgICAgICBnYXRoZXJfdGhyZWF0X2ludGVsKGludGVsX3RhcmdldCwgc2V0dGluZ3MpLAogICAgICAgICAgICAgICAgKQogICAgICAgICAgICAgICAgcmVwb3J0LnRocmVhdF9pbnRlbCA9IGludGVsCg==", ""),
    ("app/pipeline.py", "", ""),
]

def main():
    # 1) Creation du nouvel analyseur (idempotent + validation AST).
    content = d(NEW_FILE_B64)
    ast.parse(content)
    if os.path.exists(NEW_FILE):
        print("[SKIP] %s existe deja" % NEW_FILE)
    else:
        with open(NEW_FILE, "w", encoding="utf-8") as f:
            f.write(content)
        print("[OK]   cree %s" % NEW_FILE)

    # 2) Editions ancrees (idempotentes, abort si ancre manquante, AST validee).
    for path, old_b, new_b in EDITS:
        old, new = d(old_b), d(new_b)
        with open(path, encoding="utf-8") as f:
            src = f.read()
        if new in src:
            print("[SKIP] %s : deja applique" % path)
            continue
        if old not in src:
            print("[ABORT] %s : ancre introuvable -> aucune ecriture" % path)
            sys.exit(1)
        src2 = src.replace(old, new, 1)
        ast.parse(src2)
        with open(path, "w", encoding="utf-8") as f:
            f.write(src2)
        print("[OK]   %s : patch applique" % path)

    print("\nTermine. Verifiez puis reconstruisez le conteneur.")

if __name__ == "__main__":
    main()
